using System.Linq;
using UnityEngine;
namespace FootballDynasty {
 public sealed class FootballAgent:MonoBehaviour {
  public Player Data;public int Team;public Rigidbody Body;public float Energy=100;private FootballSimulator game;private Vector3 anchor;private float kickCooldown;private Transform[] legs;
  public float LeftLegAngle=>legs[0].localEulerAngles.x;public float RightLegAngle=>legs[1].localEulerAngles.x;
  public void Initialize(FootballSimulator owner,Player player,int team,int index,Color kit){game=owner;Data=player;Team=team;float sign=team==0?1:-1;int count=Career.Formations[game.Career.Team(player.club).formation].Count(p=>p==player.position);var previous=game.Agents.Count(a=>a.Team==team&&a.Data.position==player.position);float x=player.position=="POR"?-49:player.position=="DEF"?-30:player.position=="MED"?-10:18;float z=player.position=="POR"?0:(previous-(count-1)*.5f)*(player.position=="DEL"?14:11);anchor=new Vector3(x*sign,.9f,z);transform.position=anchor;Body=gameObject.AddComponent<Rigidbody>();Body.mass=75;Body.constraints=RigidbodyConstraints.FreezeRotation;Body.interpolation=RigidbodyInterpolation.Interpolate;var capsule=gameObject.AddComponent<CapsuleCollider>();capsule.radius=.3f;capsule.height=1.8f;Part(PrimitiveType.Capsule,new Vector3(0,.26f,0),new Vector3(.55f,.45f,.4f),kit);Part(PrimitiveType.Sphere,new Vector3(0,.84f,0),Vector3.one*.36f,new Color(.57f,.38f,.25f));Part(PrimitiveType.Sphere,new Vector3(0,.98f,0),new Vector3(.37f,.15f,.36f),new Color(.11f,.08f,.07f));legs=new Transform[2];for(int side=0;side<2;side++){float s=side==0?-1:1;legs[side]=Part(PrimitiveType.Capsule,new Vector3(s*.15f,-.48f,0),new Vector3(.17f,.3f,.17f),Color.white).transform;var shoe=Part(PrimitiveType.Cube,new Vector3(s*.15f,-.82f,.05f),new Vector3(.19f,.13f,.35f),new Color(.12f,.13f,.14f));shoe.transform.SetParent(legs[side],true);Part(PrimitiveType.Capsule,new Vector3(s*.38f,.22f,0),new Vector3(.14f,.32f,.14f),kit);} }
  GameObject Part(PrimitiveType type,Vector3 at,Vector3 scale,Color color){var p=GameObject.CreatePrimitive(type);p.transform.SetParent(transform,false);p.transform.localPosition=at;p.transform.localScale=scale;p.GetComponent<Renderer>().sharedMaterial=game.Material(color);Destroy(p.GetComponent<Collider>());return p;}
  public void ResetPosition(){Body.position=anchor;Body.linearVelocity=Vector3.zero;}
  public void Step(Vector3 input,bool human,bool sprint){kickCooldown=Mathf.Max(0,kickCooldown-Time.fixedDeltaTime);float dir=Team==0?1:-1;Vector3 toward=input;if(!human){var ball=game.Ball.position;FootballAgent nearest=null;float nearestDistance=float.PositiveInfinity;foreach(var agent in game.Agents){if(agent.Team!=Team||agent.Data.position=="POR")continue;float distance=(agent.Body.position-ball).sqrMagnitude;if(distance<nearestDistance){nearestDistance=distance;nearest=agent;}}Vector3 target=anchor;
    if(Data.position=="POR")target=new Vector3(-dir*49,.9f,Mathf.Clamp(ball.z*.45f,-3.2f,3.2f));else if(nearest==this){target=Vector3.Distance(transform.position,ball)<1.1f?new Vector3(dir*51,.9f,transform.position.z*.85f):ball;}else target.x=Mathf.Clamp(anchor.x+ball.x*.17f,-44,44);toward=(target-transform.position);toward.y=0;toward=Vector3.ClampMagnitude(toward,1);if(Vector3.Distance(transform.position,ball)<1.2f){if(dir*transform.position.x>29)Kick(false);else if(Data.position!="POR"&&IsUnderPressure())Kick(true);}}
   if(Data.position=="POR"&&kickCooldown<=0&&Vector3.Distance(Body.position,game.Ball.position)<1.5f&&game.Ball.position.y<1.8f){var velocity=game.Ball.linearVelocity;game.Ball.linearVelocity=new Vector3(dir*(8+Data.stats.REF/10f),Mathf.Max(1,velocity.y*.25f),-game.Ball.position.z*.5f);kickCooldown=.8f;}
   bool running=sprint&&human&&Energy>10&&toward.sqrMagnitude>.1f;Energy=Mathf.Clamp(Energy+Time.fixedDeltaTime*(running?-4:1.7f),0,100);float speed=(4.3f+Data.stats.RIT/30f)*(running?1.4f:1)*(0.8f+Energy/500);var current=Body.linearVelocity;var desired=toward*speed;var planar=new Vector3(current.x,0,current.z);var next=Vector3.MoveTowards(planar,desired,Time.fixedDeltaTime*(toward.sqrMagnitude>.05f?11:15));Body.linearVelocity=new Vector3(next.x,current.y,next.z);if(toward.sqrMagnitude>.02f)transform.rotation=Quaternion.Slerp(transform.rotation,Quaternion.LookRotation(toward),Time.fixedDeltaTime*9);for(int i=0;i<2;i++)legs[i].localRotation=Quaternion.Euler(Mathf.Sin(Time.time*12+i*Mathf.PI)*next.magnitude*4,0,0);
   var pos=Body.position;pos.x=Mathf.Clamp(pos.x,-51.5f,51.5f);pos.z=Mathf.Clamp(pos.z,-33,33);Body.position=pos;if(Vector3.Distance(pos,game.Ball.position)<.95f&&kickCooldown<=0&&toward.sqrMagnitude>.1f){var target=pos+toward.normalized*.7f;target.y=.13f;var delta=target-game.Ball.position;game.Ball.AddForce(Vector3.ClampMagnitude(delta*18,12),ForceMode.Acceleration);}
  }
  bool IsUnderPressure(){foreach(var agent in game.Agents)if(agent.Team!=Team&&(agent.Body.position-Body.position).sqrMagnitude<6.25f)return true;return false;}
  public void Kick(bool pass){if(kickCooldown>0||Vector3.Distance(transform.position,game.Ball.position)>1.8f)return;float dir=Team==0?1:-1;Vector3 target=new Vector3(dir*55,.2f,0);float speed=24+Data.stats.TIR/8f;float lift=3.8f;if(pass){var mate=game.Agents.Where(a=>a.Team==Team&&a!=this&&a.Data.position!="POR").OrderBy(a=>Vector3.Distance(a.transform.position,transform.position)-dir*(a.transform.position.x-transform.position.x)*.3f).First();target=mate.transform.position;speed=15+Data.stats.PAS/12f;lift=.4f;if(this==game.Controlled)game.Controlled=mate;}var vector=target-game.Ball.position;vector.y=0;float skill=pass?Data.stats.PAS:Data.stats.TIR;float error=(100-skill)*.045f*(1+(100-Energy)/100f);float turn=Vector3.Angle(transform.forward,vector);error*=1+turn/180f;vector=Quaternion.Euler(0,Random.Range(-error,error),0)*vector;game.Ball.linearVelocity=vector.normalized*speed+Vector3.up*lift;game.Ball.angularVelocity=Vector3.Cross(Vector3.up,vector.normalized)*(pass?8:20)+Vector3.up*Random.Range(-3f,3f);kickCooldown=.75f;}
 }
}
